import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const dist = path.join(root, "dist");
// Invoke the TypeScript compiler's JS entry directly through Node so the build works on every
// platform (the node_modules/.bin/tsc shim is not directly executable on Windows).
const tscJs = path.join(root, "node_modules", "typescript", "bin", "tsc");

fs.rmSync(dist, { recursive: true, force: true });
fs.mkdirSync(dist, { recursive: true });

execFileSync(
  process.execPath,
  [
    tscJs,
    "-p",
    "tsconfig.json",
    "--outDir",
    "dist/esm",
    "--declarationDir",
    "dist/types",
  ],
  {
    cwd: root,
    stdio: "inherit",
  },
);

for (const file of fs.readdirSync(path.join(dist, "types"))) {
  if (file.endsWith(".d.ts")) {
    copyAs(`dist/types/${file}`, `dist/${file}`);
  }
}

await writeRuntimeFiles();
await writeCssVariables();

fs.rmSync(path.join(dist, "types"), { recursive: true, force: true });

function copyAs(from, to) {
  fs.copyFileSync(path.join(root, from), path.join(root, to));
}

async function writeCssVariables() {
  const tokens = await import(pathToFileURL(path.join(root, "dist/index.mjs")));
  fs.writeFileSync(
    path.join(dist, "css-variables.css"),
    renderCssVariables(tokens),
    "utf8",
  );
}

async function writeRuntimeFiles() {
  const index = await import(
    pathToFileURL(path.join(root, "dist/esm/index.js"))
  );
  const tailwind = await import(
    pathToFileURL(path.join(root, "dist/esm/tailwind-preset.js"))
  );

  fs.writeFileSync(
    path.join(dist, "index.mjs"),
    `export * from "./esm/index.js";\n`,
    "utf8",
  );
  fs.writeFileSync(
    path.join(dist, "tailwind-preset.mjs"),
    `export { avoro, default } from "./esm/tailwind-preset.js";\n`,
    "utf8",
  );

  fs.writeFileSync(
    path.join(dist, "index.cjs"),
    `const colors = ${serialize(index.colors)};
const chart = ${serialize(index.chart)};
const typography = ${serialize(index.typography)};
const space = ${serialize(index.space)};
const radius = ${serialize(index.radius)};
const border = ${serialize(index.border)};
const shadow = ${serialize(index.shadow)};
const duration = ${serialize(index.duration)};
const easing = ${serialize(index.easing)};
const surfaces = ${serialize(index.surfaces)};
const semantic = ${serialize(index.semantic)};
const componentTokens = ${serialize(index.componentTokens)};
const breakpoints = ${serialize(index.breakpoints)};
const layout = ${serialize(index.layout)};
const avoroTokens = { colors, chart, typography, space, radius, border, shadow, duration, easing, surfaces, semantic, componentTokens, breakpoints, layout };

module.exports = {
  avoroTokens,
  border,
  breakpoints,
  chart,
  colors,
  componentTokens,
  duration,
  easing,
  layout,
  radius,
  semantic,
  shadow,
  space,
  surfaces,
  typography
};
`,
    "utf8",
  );

  fs.writeFileSync(
    path.join(dist, "tailwind-preset.cjs"),
    `const avoro = ${serialize(tailwind.avoro)};

module.exports = {
  avoro,
  default: avoro
};
`,
    "utf8",
  );
}

function renderCssVariables(tokens) {
  const {
    colors,
    typography,
    space,
    radius,
    border,
    shadow,
    duration,
    easing,
    surfaces,
    semantic,
    componentTokens,
    breakpoints,
    layout,
    chart,
  } = tokens;

  return `/* ==========================================================================
   Avoro Design Tokens - CSS Custom Properties
   v1.0.0
   Generated from @avoro/brand-tokens src/tokens.ts.
   ========================================================================== */

:root {
  /* Brand color */
  --avoro-chartreuse: ${colors.brand.chartreuse};
  --avoro-chartreuse-deep: ${colors.brand.chartreuseDeep};
  --avoro-chartreuse-bright: ${colors.brand.chartreuseBright};

  /* Neutral system */
  --avoro-ink: ${colors.neutral.ink};
  --avoro-ink-soft: ${colors.neutral.inkSoft};
  --avoro-paper: ${colors.neutral.paper};
  --avoro-soft: ${colors.neutral.soft};
  --avoro-fog: ${colors.neutral.fog};
  --avoro-smoke: ${colors.neutral.smoke};

  /* Functional */
  --avoro-success: ${colors.functional.success};
  --avoro-warning: ${colors.functional.warning};
  --avoro-error: ${colors.functional.error};

  /* Type families */
  --avoro-font-display: ${typography.family.display};
  --avoro-font-mono: ${typography.family.mono};

  /* Type weights */
${cssMap("weight", typography.weight)}

  /* Type scale */
${cssTypeScale(typography.size)}

  /* Spacing */
${cssMap("space", space)}

  /* Radius */
${cssMap("radius", radius)}

  /* Borders */
${cssMap("border", border)}

  /* Shadow */
${cssMap("shadow", shadow)}

  /* Motion */
${cssMap("duration", duration)}
${cssMap("ease", easing)}

  /* Semantic tokens (light + dark) */
${cssFlatten("semantic", semantic)}

  /* Semantic aliases (default: light values; overridden on dark surface) */
${cssSemanticAliases(semantic.light)}

  /* Component tokens */
${cssFlatten("component", componentTokens)}

  /* Breakpoints */
${cssFlatten("breakpoint", breakpoints)}

  /* Layout */
${cssFlatten("layout", layout)}

  /* Chart series palette */
${cssFlatten("chart", chart)}
}

[data-avoro-surface="dark"] {
  /* Semantic aliases (dark values) */
${cssSemanticAliases(semantic.dark)}

  --avoro-bg: var(--avoro-ink);
  --avoro-bg-soft: var(--avoro-ink-soft);
  --avoro-fg: var(--avoro-paper);
  --avoro-fg-soft: var(--avoro-fog);
  --avoro-fg-muted: var(--avoro-smoke);
  --avoro-accent: var(--avoro-chartreuse);
  --avoro-border: rgba(250, 250, 247, 0.10);

  /* Surface ramp (three levels) + inverse panel */
  --avoro-canvas: ${surfaces.dark.canvas};
  --avoro-surface: ${surfaces.dark.surface};
  --avoro-surface-raised: ${surfaces.dark.surfaceRaised};
  --avoro-surface-inverse: ${surfaces.dark.surfaceInverse};

  /* Subtle border + selection highlight */
  --avoro-border-subtle: ${surfaces.dark.borderSubtle};
  --avoro-highlight: ${surfaces.dark.highlight};

  /* Chart ramp */
  --avoro-chart-bar: ${surfaces.dark.chartBar};
  --avoro-chart-track: ${surfaces.dark.chartTrack};
  --avoro-chart-fill: ${surfaces.dark.chartFill};

  /* Chartreuse-as-text (accessible on this surface) */
  --avoro-chartreuse-text: var(--avoro-chartreuse);

  /* Functional colors, dark-theme values */
  --avoro-success: ${surfaces.dark.success};
  --avoro-warning: ${surfaces.dark.warning};
  --avoro-error: ${surfaces.dark.error};
}

:root:not([data-avoro-surface='dark']) {
  --avoro-bg: var(--avoro-paper);
  --avoro-bg-soft: var(--avoro-soft);
  --avoro-fg: var(--avoro-ink);
  --avoro-fg-soft: var(--avoro-ink-soft);
  --avoro-fg-muted: var(--avoro-smoke);
  --avoro-accent: var(--avoro-chartreuse-deep);
  --avoro-border: var(--avoro-fog);

  /* Surface ramp (three levels) + inverse panel */
  --avoro-canvas: ${surfaces.light.canvas};
  --avoro-surface: ${surfaces.light.surface};
  --avoro-surface-raised: ${surfaces.light.surfaceRaised};
  --avoro-surface-inverse: ${surfaces.light.surfaceInverse};

  /* Subtle border + selection highlight */
  --avoro-border-subtle: ${surfaces.light.borderSubtle};
  --avoro-highlight: ${surfaces.light.highlight};

  /* Chart ramp */
  --avoro-chart-bar: ${surfaces.light.chartBar};
  --avoro-chart-track: ${surfaces.light.chartTrack};
  --avoro-chart-fill: ${surfaces.light.chartFill};

  /* Chartreuse-as-text (accessible on this surface) */
  --avoro-chartreuse-text: var(--avoro-chartreuse-deep);
}
`;
}

function cssFlatten(prefix, values) {
  const lines = [];
  const walk = (obj, parts) => {
    for (const [key, value] of Object.entries(obj)) {
      const next = [...parts, toKebab(key)];
      if (typeof value === "object" && value !== null) walk(value, next);
      else lines.push(`  --avoro-${prefix}-${next.join("-")}: ${value};`);
    }
  };
  walk(values, []);
  return lines.join("\n");
}

function cssSemanticAliases(mode) {
  const lines = [];
  const walk = (obj, parts) => {
    for (const [key, value] of Object.entries(obj)) {
      const next = [...parts, toKebab(key)];
      if (typeof value === "object" && value !== null) walk(value, next);
      else lines.push(`  --avoro-${next.join("-")}: ${value};`);
    }
  };
  walk(mode, []);
  return lines.join("\n");
}

function cssMap(prefix, values) {
  return Object.entries(values)
    .map(([key, value]) => `  --avoro-${prefix}-${toKebab(key)}: ${value};`)
    .join("\n");
}

function cssTypeScale(values) {
  return Object.entries(values)
    .flatMap(([key, value]) => [
      `  --avoro-size-${toKebab(key)}: ${value.value};`,
      `  --avoro-track-${toKebab(key)}: ${value.tracking};`,
      `  --avoro-leading-${toKebab(key)}: ${value.leading};`,
    ])
    .join("\n");
}

function toKebab(value) {
  return String(value).replace(/[A-Z]/g, (match) => `-${match.toLowerCase()}`);
}

function serialize(value) {
  return JSON.stringify(value, null, 2);
}
